from AlgorithmImports import *
from datetime import timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda u: u.Strikes(-100, 100).Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_closes = []
        self.slow_closes = []
        self.bucket_end = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.spy_cleanup_ticket = None
        self.expiration_block_date = None

    def OnData(self, slice):
        today = self.Time.date()

        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if self.spy_cleanup_ticket is None or not self.spy_cleanup_ticket.Status.IsOpen():
                self.Debug("Unexpected SPY exercise/assignment; liquidating")
                self.spy_cleanup_ticket = self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Unexpected exercise/assignment"
                )

        self._process_expiration(today)
        self._process_option_exit(slice, today)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar, slice, today)

    def _process_minute_bar(self, bar, slice, today):
        end = bar.EndTime

        if end.date() != today:
            return

        if end.time() < time(9, 30) or end.time() > time(16, 0):
            return

        if end.time() < time(9, 35):
            bucket_end = end.replace(
                hour=9, minute=35, second=0, microsecond=0
            )
        else:
            minutes = (end.hour * 60 + end.minute) - (9 * 60 + 35)
            bucket_end = (
                end.replace(hour=0, minute=0, second=0, microsecond=0)
                + timedelta(minutes=9 * 60 + 35 + (minutes // 5) * 5)
            )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finish_bucket(slice, self.bucket_end)
            self.bucket_closes = {}

        self.bucket_end = bucket_end
        self.bucket_closes[(end.hour, end.minute)] = bar.Close

        if end >= bucket_end:
            self._finish_bucket(slice, bucket_end)
            self.bucket_closes = {}
            self.bucket_end = None

    def _finish_bucket(self, slice, bucket_end):
        expected = set()

        for i in range(5):
            t = bucket_end - timedelta(minutes=i)
            expected.add((t.hour, t.minute))

        if set(self.bucket_closes.keys()) != expected:
            return

        close = self.bucket_closes[
            (bucket_end.hour, bucket_end.minute)
        ]

        previous_fast = (
            sum(self.fast_closes[-5:]) / 5
            if len(self.fast_closes) >= 5
            else None
        )

        previous_slow = (
            sum(self.slow_closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD
            if len(self.slow_closes) >= self.SLOW_PERIOD
            else None
        )

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < self.SLOW_PERIOD:
            return

        current_fast = sum(self.fast_closes[-5:]) / 5
        current_slow = (
            sum(self.slow_closes[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD
        )

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            time(9, 45) <= bucket_end.time() <= time(14, 30)
        )

        if crossover and eligible_time:
            self._try_entry(slice, close)

    def _try_entry(self, slice, spy_price):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
            return

        if (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Quantity > 0
        ):
            return

        chains = [
            chain
            for chain in slice.OptionChains.Values
            if chain.Symbol == self.option_symbol
        ]

        if not chains:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)

        contracts = [
            contract
            for chain in chains
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = min(
            contract.Expiry.date()
            for contract in contracts
        )

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= 1.01 * spy_price
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _process_option_exit(self, slice, today):
        if self.entry_symbol is None:
            return

        if self.Portfolio[self.entry_symbol].Quantity <= 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            return

        held_contract = None

        for chain in slice.OptionChains.Values:
            held_contract = next(
                (
                    contract
                    for contract in chain
                    if contract.Symbol == self.entry_symbol
                ),
                None
            )

            if held_contract is not None:
                break

        profit_target = False

        if held_contract is not None and self.entry_price is not None:
            bid = held_contract.BidPrice
            ask = held_contract.AskPrice

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2
                profit_target = midpoint >= 1.50 * self.entry_price

        expiry_date = self.entry_symbol.ID.Date.date()
        prior_trading_day = self._previous_trading_day(expiry_date)

        time_stop = (
            today == prior_trading_day
            and self.Time.time() >= time(15, 45)
        )

        if profit_target or time_stop:
            reason = (
                "50% profit target"
                if profit_target
                else "expiration-eve time stop"
            )

            quantity = self.Portfolio[self.entry_symbol].Quantity

            self.exit_ticket = self.MarketOrder(
                self.entry_symbol,
                -quantity,
                tag=reason
            )

            self.Debug("Exit submitted: " + reason)

    def _process_expiration(self, today):
        if self.entry_symbol is None:
            return

        expiry_date = self.entry_symbol.ID.Date.date()

        if today < expiry_date:
            return

        self.expiration_block_date = today

        quantity = self.Portfolio[self.entry_symbol].Quantity

        if quantity > 0:
            if (
                self.exit_ticket is None
                or not self.exit_ticket.Status.IsOpen()
            ):
                self.exit_ticket = self.MarketOrder(
                    self.entry_symbol,
                    -quantity,
                    tag="Expiration safeguard"
                )

                self.Debug("Expiration safeguard exit submitted")

    def _previous_trading_day(self, date):
        previous = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous):
            previous -= timedelta(days=1)

        return previous

    def OnOrderEvent(self, order_event):
        if order_event.Status in [
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ]:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.FillQuantity > 0
            ):
                self.entry_price = order_event.FillPrice

                self.Debug(
                    "Entry filled: "
                    + str(self.entry_symbol)
                    + " at "
                    + str(self.entry_price)
                )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]
        ):
            self.Debug(
                "Entry order failed: "
                + str(order_event.Status)
            )

            self.entry_ticket = None
            self.entry_symbol = None
            self.entry_price = None

        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self.Debug(
                "Unexpected option exercise/assignment received"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]
        ):
            if order_event.Status != OrderStatus.Filled:
                self.Debug(
                    "Exit order failed: "
                    + str(order_event.Status)
                )

            self.exit_ticket = None

            if (
                self.entry_symbol is not None
                and self.Portfolio[self.entry_symbol].Quantity == 0
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
