from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteBar:
    def __init__(self, end_time, open_price, high, low, close, volume):
        self.EndTime = end_time
        self.Open = open_price
        self.High = high
        self.Low = low
        self.Close = close
        self.Volume = volume


class SpyCallCrossover(QCAlgorithm):

    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option.Symbol

        # Broad universe: weekly options, 0-730 DTE, and wide strike range.
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-1000, 1000)
                       .Expiration(0, 730)
        )

        self.fast_values = []
        self.slow_values = []

        self._bucket_end = None
        self._minute_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.equity_liquidation_ticket = None
        self._expiration_processing_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Never intentionally carry an option into expiration.
        if self.held_symbol is not None:
            expiration_date = self.held_symbol.ID.Date.date()

            if current_date >= expiration_date:
                self._expiration_processing_date = current_date
                self._SubmitExit("expiration processing")

            else:
                previous_trading_day = self._PreviousTradingDay(expiration_date)

                if (
                    current_date == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self._SubmitExit("expiration time stop")

        # Handle any unexpected SPY equity position caused by exercise/assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            if (
                self.equity_liquidation_ticket is None
                or not self.Transactions.GetOrderTicket(
                    self.equity_liquidation_ticket.OrderId
                ).Status.IsOpen()
            ):
                self.Debug(
                    "Unexpected SPY equity position detected; liquidating immediately."
                )
                self.equity_liquidation_ticket = self.MarketOrder(
                    self.spy,
                    -spy_quantity,
                    tag="Unexpected exercise/assignment liquidation"
                )

        # Evaluate the profit target on every minute Slice.
        self._EvaluateProfitTarget(slice)

        # Process the current SPY minute bar into an aligned five-minute bar.
        if slice.Bars.ContainsKey(self.spy):
            self._ProcessMinuteBar(slice.Bars[self.spy], slice)

    def _ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime

        # Regular-session bars only.
        if end_time.time() <= time(9, 30) or end_time.time() > time(16, 0):
            return

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5

        bucket_end = end_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_minute)

        if self._bucket_end is None:
            self._bucket_end = bucket_end

        if bucket_end != self._bucket_end:
            self._FinalizeBucket(slice)
            self._minute_bars = {}
            self._bucket_end = bucket_end

        self._minute_bars[end_time] = bar

        if end_time.time() == time(16, 0):
            self._FinalizeBucket(slice)
            self._minute_bars = {}
            self._bucket_end = None

    def _FinalizeBucket(self, slice: Slice):
        if self._bucket_end is None:
            return

        expected = [
            self._bucket_end - timedelta(minutes=i)
            for i in range(5, 0, -1)
        ]

        # Missing minutes mean the five-minute bar is missing.
        if any(t not in self._minute_bars for t in expected):
            return

        bars = [self._minute_bars[t] for t in expected]

        consolidated = FiveMinuteBar(
            self._bucket_end,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars)
        )

        self._OnFiveMinuteBar(consolidated, slice)

    def _OnFiveMinuteBar(self, bar: FiveMinuteBar, slice: Slice):
        self.fast_values.append(bar.Close)
        self.slow_values.append(bar.Close)

        if len(self.fast_values) > self.FAST_PERIOD:
            self.fast_values.pop(0)

        if len(self.slow_values) > self.SLOW_PERIOD:
            self.slow_values.pop(0)

        if (
            len(self.fast_values) < self.FAST_PERIOD
            or len(self.slow_values) < self.SLOW_PERIOD
        ):
            return

        fast_current = sum(self.fast_values[-self.FAST_PERIOD:]) / self.FAST_PERIOD
        slow_current = sum(self.slow_values[-self.SLOW_PERIOD:]) / self.SLOW_PERIOD

        if not hasattr(self, "_previous_fast"):
            self._previous_fast = fast_current
            self._previous_slow = slow_current
            return

        bullish_cross = (
            self._previous_fast <= self._previous_slow
            and fast_current > slow_current
        )

        self._previous_fast = fast_current
        self._previous_slow = slow_current

        bar_end_time = bar.EndTime.time()

        if not (
            time(9, 45) <= bar_end_time <= time(14, 30)
        ):
            return

        if not bullish_cross:
            return

        if self._expiration_processing_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None:
            order = self.Transactions.GetOrderTicket(self.entry_ticket.OrderId)
            if order is not None and order.Status.IsOpen():
                return

        if not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        current_price = slice.Bars[self.spy].Close
        chain = slice.OptionChains[self.option] if slice.OptionChains.ContainsKey(
            self.option
        ) else None

        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration satisfies the 7-day rule.")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = current_price * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiration
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call strike is at least 1% out of the money."
            )
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

        self.Debug(
            "Entry submitted: {0}, strike {1}, expiry {2}".format(
                selected.Symbol,
                selected.Strike,
                nearest_expiration
            )
        )

    def _EvaluateProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None:
            order = self.Transactions.GetOrderTicket(self.exit_ticket.OrderId)
            if order is not None and order.Status.IsOpen():
                return

        bid = None
        ask = None

        if slice.QuoteBars.ContainsKey(self.held_symbol):
            quote = slice.QuoteBars[self.held_symbol]

            if quote.Bid is not None:
                bid = quote.Bid.Close

            if quote.Ask is not None:
                ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._SubmitExit("50% profit target")

    def _SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None:
            order = self.Transactions.GetOrderTicket(self.exit_ticket.OrderId)
            if order is not None and order.Status.IsOpen():
                return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {0}; quantity {1}".format(
                reason,
                quantity
            )
        )

    def _PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None

                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.equity_liquidation_ticket is not None
            and order_event.OrderId == self.equity_liquidation_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Unexpected SPY equity position liquidated.")
            self.equity_liquidation_ticket = None
