        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 365)
        )

        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.exit_ticket = None
        self.blocked_entry_date = None

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self.ExpirationGuard
        )

    def OnData(self, slice: Slice):
        self.LiquidateUnexpectedSpyPosition()

        if self.spy in slice.Bars:
            self.ConsumeMinuteBar(slice.Bars[self.spy], slice)

        if self.held_symbol is not None:
            self.CheckMinuteExit(slice)

    def ConsumeMinuteBar(self, bar: TradeBar, slice: Slice):
        local = self.Time
        current_date = local.date()
        current_time = local.time()

        if current_time < time(9, 30) or current_time >= time(16, 0):
            return

        minutes_from_open = (
            current_time.hour * 60 + current_time.minute
            - (9 * 60 + 30)
        )
        bucket_start = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            9,
            30
        ) + timedelta(minutes=(minutes_from_open // 5) * 5)

        if self.bucket_start != bucket_start:
            self.FinishBucket(slice)
            self.bucket_start = bucket_start
            self.bucket_closes = {}

        self.bucket_closes[local] = bar.Close

        if current_time.minute % 5 == 4:
            self.FinishBucket(slice)
            self.bucket_start = None
            self.bucket_closes = {}

    def FinishBucket(self, slice: Slice):
        if self.bucket_start is None or len(self.bucket_closes) != 5:
            return

        values = sorted(self.bucket_closes.items())

        if any(
            values[i][0] - values[i - 1][0] != timedelta(minutes=1)
            for i in range(1, len(values))
        ):
            return

        close = values[-1][1]

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.slow_values) > self.SLOW_PERIOD:
            self.slow_values.pop(0)

        current_fast = (
            sum(self.fast_values[-self.FAST_PERIOD:]) / self.FAST_PERIOD
            if len(self.fast_values) >= self.FAST_PERIOD
            else None
        )

        current_slow = (
            sum(self.slow_values) / self.SLOW_PERIOD
            if len(self.slow_values) >= self.SLOW_PERIOD
            else None
        )

        bar_end = self.bucket_start + timedelta(minutes=5)

        previous_fast = self.previous_fast
        previous_slow = self.previous_slow

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if None in (current_fast, current_slow, previous_fast, previous_slow):
            return

        bullish = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if not bullish or not eligible_time:
            return

        if (
            self.blocked_entry_date == bar_end.date()
            or self.held_symbol is not None
            or self.entry_order_id is not None
        ):
            return

        self.TryEnter(slice, close, bar_end.date())

    def TryEnter(self, slice: Slice, spy_price: float, algorithm_date):
        if self.option.Symbol not in slice.OptionChains:
            self.Debug("Skipped selection: no option chain")
            return

        contracts = list(
            slice.OptionChains[self.option.Symbol].Contracts.Values
        )

        minimum_expiry = algorithm_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(
                "Skipped selection: no expiration at least 7 calendar days out"
            )
            return

        selected_expiry = expiries[0]

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= 1.01 * spy_price
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped selection: no qualifying call at selected expiration"
            )
            return

        contract = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_symbol = contract.Symbol
        self.entry_ticket = self.MarketOrder(
            contract.Symbol,
            1,
            tag="Bullish MA crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                contract.Symbol,
                selected_expiry,
                contract.Strike
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_symbol
                self.entry_fill_price = order_event.FillPrice

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_fill_price
                    )
                )

                self.entry_ticket = None
                self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry not filled: {}".format(order_event.Status))
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None

            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} at {:.4f}".format(
                    self.held_symbol,
                    order_event.FillPrice
                )
            )
            self.ClearPositionState()

    def CheckMinuteExit(self, slice: Slice):
        symbol = self.held_symbol
        expiry_date = symbol.ID.Date.date()
        previous_trading_day = self.PreviousTradingDay(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration-eve time stop")
            return

        if symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[symbol]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            return

        self.CancelOpenExit()

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag=reason
            )
            self.Debug(
                "Exit submitted: {} ({})".format(
                    self.held_symbol,
                    reason
                )
            )

    def ExpirationGuard(self):
        if (
            self.held_symbol is not None
            and self.held_symbol.ID.Date.date() <= self.Time.date()
        ):
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration processing safeguard")

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected exercise or assignment: liquidating SPY equity"
        )
        self.blocked_entry_date = self.Time.date()
        self.LiquidateUnexpectedSpyPosition()

    def LiquidateUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position: liquidating {} shares".format(
                    quantity
                )
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise/assignment cleanup"
            )
            self.blocked_entry_date = self.Time.date()

    def PreviousTradingDay(self, date):
        candidate = date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            candidate
        ):
            candidate -= timedelta(days=1)

        return candidate

    def CancelOpenExit(self):
        if (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        ):
            self.exit_ticket.Cancel("Replacing exit order")

    def ClearPositionState(self):
        self.held_symbol = None
        self.entry_fill_price = None
        self.exit_ticket = None
        self.entry_symbol = None

