            return

        bar = slice.Bars[self.spy.Symbol]
        self._process_minute_bar(bar)

    def _process_minute_bar(self, minute_bar: TradeBar):
        end_time = minute_bar.EndTime
        local_time = end_time.time()

        # Regular-session minute bars end from 09:31 through 16:00.
        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        # The first five-minute bar ends at 09:35. New aligned intervals
        # begin on minute bars ending at :01, :06, :11, etc.
        if end_time.minute % 5 == 1:
            self._minute_buffer = [minute_bar]
            return

        if not self._minute_buffer:
            return

        previous_end = self._minute_buffer[-1].EndTime
        if end_time - previous_end != timedelta(minutes=1):
            self._minute_buffer = []
            return

        self._minute_buffer.append(minute_bar)

        if len(self._minute_buffer) < 5:
            return

        bars = self._minute_buffer
        self._minute_buffer = []

        if bars[-1].EndTime.minute % 5 != 0:
            return

        consolidated = TradeBar(
            bars[0].Time,
            self.spy.Symbol,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated)

    def _on_five_minute_bar(self, bar: TradeBar):
        self._previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self._previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter()

    def _try_enter(self):
        today = self.Time.date()

        if self._blocked_entry_date == today:
            return

        if self._held_option is not None:
            return

        if self._entry_ticket is not None and self._is_open_ticket(self._entry_ticket):
            return

        if self._current_slice is None or not self._current_slice.OptionChains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price is unavailable.")
            return

        candidates = []

        for chain in self._current_slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                days_to_expiry = (expiry_date - today).days

                if days_to_expiry < 7:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)

        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _handle_option_exits(self):
        if self._held_option is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._held_option]
        if not holding.Invested or holding.Quantity <= 0:
            return

        contract = self._find_current_contract(self._held_option)

        # Profit-target testing is skipped when quote data is unavailable.
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("profit target")

    def _handle_expiration_processing(self):
        if self._held_option is None:
            return

        holding = self.Portfolio[self._held_option]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiry_date = self._held_option.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self._blocked_entry_date = today
            self._submit_exit("expiration protection")
            return

        if (
            self.Time.time() >= time(15, 45)
            and self._is_immediately_preceding_trading_day(today, expiry_date)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self._held_option is None:
            return

        holding = self.Portfolio[self._held_option]
        quantity = holding.Quantity

        if quantity <= 0:
            return

        if self._exit_ticket is not None and self._is_open_ticket(self._exit_ticket):
            self._exit_ticket.Cancel("Replacing exit order")

        self._exit_ticket = self.MarketOrder(
            self._held_option,
            -quantity
        )

        self.Debug(
            "Exit submitted: {} reason={}".format(
                self._held_option,
                reason
            )
        )

    def _find_current_contract(self, symbol):
        if self._current_slice is None:
            return None

        for chain in self._current_slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract

        return None

    def _is_immediately_preceding_trading_day(self, today, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while True:
            candidate_dt = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

            if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
                candidate_dt
            ):
                return today == candidate

            candidate -= timedelta(days=1)

    def _handle_unexpected_spy_position(self):
        spy_holding = self.Portfolio[self.spy.Symbol]

        if spy_holding.Quantity != 0:
            self._blocked_entry_date = self.Time.date()
            self.Debug(
                "Unexpected SPY exercise or assignment position detected; "
                "liquidating {} shares.".format(spy_holding.Quantity)
            )
            self.MarketOrder(
                self.spy.Symbol,
                -spy_holding.Quantity
            )

    def _is_open_ticket(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_option = order_event.Symbol
                self._entry_price = order_event.FillPrice

                self.Debug(
                    "Entry filled: {} price={}".format(
                        self._held_option,
                        self._entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self._entry_ticket = None

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} price={}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )

            self._exit_ticket = None
            self._entry_ticket = None
            self._held_option = None
            self._entry_price = None

